// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import java.lang.foreign.Arena;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.LockSupport;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Closes the shared native arenas of released {@link LmdbAdjacencyArena}s on one daemon thread.
 * <p>
 * Closing a shared {@link Arena} handshakes every Java thread and costs tens of microseconds. A base fold releases
 * every single-commit arena that the range merges since the previous fold kept alive as a source, thousands at once,
 * and the applier thread that releases them has committers waiting on its next publish. The adjacency arena is closed
 * to its users at once; only the native memory is freed a moment later, here. Past a backlog of
 * {@value #INLINE_BACKLOG} arenas the releasing thread closes inline, so the backlog's memory stays bounded.
 */
final class LmdbAdjacencyArenaReaper {

	private static final Logger logger = LoggerFactory.getLogger(LmdbAdjacencyArenaReaper.class);

	static final int INLINE_BACKLOG = 1 << 16;

	private static final ConcurrentLinkedQueue<Arena> QUEUE = new ConcurrentLinkedQueue<>();
	private static final AtomicInteger BACKLOG = new AtomicInteger();
	private static volatile boolean held;
	private static final Thread THREAD;

	static {
		THREAD = new Thread(LmdbAdjacencyArenaReaper::run, "lmdb-adjacency-arena-reaper");
		THREAD.setDaemon(true);
		THREAD.start();
	}

	private LmdbAdjacencyArenaReaper() {
	}

	/** Frees the arena's native memory on the reaper thread, or inline once the backlog is large. */
	static void closeLater(Arena arena) {
		if (BACKLOG.get() >= INLINE_BACKLOG) {
			arena.close();
			return;
		}
		BACKLOG.incrementAndGet();
		QUEUE.add(arena);
		LockSupport.unpark(THREAD);
	}

	private static void run() {
		while (true) {
			Arena arena = held ? null : QUEUE.poll();
			if (arena == null) {
				LockSupport.park(QUEUE);
				continue;
			}
			try {
				arena.close();
			} catch (RuntimeException e) {
				logger.debug("Closing a released adjacency arena failed", e);
			} finally {
				BACKLOG.decrementAndGet();
			}
		}
	}

	/** Test seam: while held, queued arenas stay open. */
	static void holdForTest(boolean hold) {
		held = hold;
		LockSupport.unpark(THREAD);
	}

	/** Test seam: waits until every queued arena has been closed. */
	static boolean awaitIdleForTest(long timeout, TimeUnit unit) throws InterruptedException {
		long deadline = System.nanoTime() + unit.toNanos(timeout);
		while (BACKLOG.get() > 0) {
			if (System.nanoTime() >= deadline) {
				return false;
			}
			LockSupport.unpark(THREAD);
			Thread.sleep(1);
		}
		return true;
	}

	static int backlogForTest() {
		return BACKLOG.get();
	}
}
